// `succeeded`: paid. `processing`: confirmation is pending; poll the invoice or order instead of
// paying again. `requires_action`: the customer must complete the returned action. `failed`: the
// attempt did not succeed, for the reason in failure_reason; a declined gateway payment is withdrawn,
// and paying again starts a new payment.
// Ref: #/components/schemas/PaymentStatus
type PaymentStatus string

const (
	PaymentStatusSucceeded      PaymentStatus = "succeeded"
	PaymentStatusProcessing     PaymentStatus = "processing"
	PaymentStatusRequiresAction PaymentStatus = "requires_action"
	PaymentStatusFailed         PaymentStatus = "failed"
)

// AllValues returns all PaymentStatus values.
func (PaymentStatus) AllValues() []PaymentStatus {
	return []PaymentStatus{
		PaymentStatusSucceeded,
		PaymentStatusProcessing,
		PaymentStatusRequiresAction,
		PaymentStatusFailed,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s PaymentStatus) MarshalText() ([]byte, error) {
	switch s {
	case PaymentStatusSucceeded:
		return []byte(s), nil
	case PaymentStatusProcessing:
		return []byte(s), nil
	case PaymentStatusRequiresAction:
		return []byte(s), nil
	case PaymentStatusFailed:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *PaymentStatus) UnmarshalText(data []byte) error {
	switch PaymentStatus(data) {
	case PaymentStatusSucceeded:
		*s = PaymentStatusSucceeded
		return nil
	case PaymentStatusProcessing:
		*s = PaymentStatusProcessing
		return nil
	case PaymentStatusRequiresAction:
		*s = PaymentStatusRequiresAction
		return nil
	case PaymentStatusFailed:
		*s = PaymentStatusFailed
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

